#include "discover.h"
#include "parse_evd.h"
#include <dirent.h>
#include <stdio.h>
#include <string.h>

#define MAX_RECORDS 512

struct record {
    char name[128];
    char fname[256];
    char fields[512];
    int written;
};

static int find_record(struct record *records, int n, const char *name) {
    for (int i = 0; i < n; i++)
        if (!records[i].written && strcmp(records[i].name, name) == 0)
            return i;
    return -1;
}

static int scan_records(struct record *records) {
    DIR *d = opendir("/app/rivetbay/evd");
    if (!d) return -1;
    int n = 0;
    struct dirent *ent;
    while ((ent = readdir(d)) != NULL && n < MAX_RECORDS) {
        size_t len = strlen(ent->d_name);
        if (len < 5 || strcmp(ent->d_name + len - 4, ".evd") != 0) continue;
        char path[512];
        snprintf(path, sizeof(path), "/app/rivetbay/evd/%s", ent->d_name);
        if (parse_evd_file(path, records[n].name, records[n].fields,
                           sizeof(records[n].fields)) != 0)
            continue;
        snprintf(records[n].fname, sizeof(records[n].fname), "%s", ent->d_name);
        records[n].written = 0;
        n++;
    }
    closedir(d);
    return n;
}

static void write_record(FILE *out, struct record *r) {
    fprintf(out, "%s|evd/%s|%s\n", r->name, r->fname, r->fields);
    r->written = 1;
}

void discover_all(void) {
    struct record records[MAX_RECORDS];
    int n = scan_records(records);
    if (n < 0) return;

    char prior[MAX_RECORDS][128];
    int np = 0;
    FILE *old = fopen("/app/rivetbay/intake/current.ledger", "r");
    if (old) {
        char line[1024];
        while (np < MAX_RECORDS && fgets(line, sizeof(line), old)) {
            char *bar = strchr(line, '|');
            if (!bar) continue;
            *bar = 0;
            char *name = line;
            while (*name == ' ' || *name == '\t') name++;
            if (!*name) continue;
            snprintf(prior[np++], sizeof(prior[0]), "%s", name);
        }
        fclose(old);
    }

    FILE *out = fopen("/app/rivetbay/intake/current.ledger", "w");
    if (!out) return;
    for (int i = 0; i < np; i++) {
        int j = find_record(records, n, prior[i]);
        if (j >= 0) write_record(out, &records[j]);
    }
    for (int i = 0; i < n; i++)
        if (!records[i].written) write_record(out, &records[i]);
    fclose(out);
}
EOF

