static void clear_emitters(void) {
    DIR *d = opendir("/app/rivetbay/emitters");
    if (!d) return;
    struct dirent *ent;
    while ((ent = readdir(d)) != NULL) {
        size_t len = strlen(ent->d_name);
        if (len > 5 && strcmp(ent->d_name + len - 5, ".kdec") == 0) {
            char path[512];
            snprintf(path, sizeof(path), "/app/rivetbay/emitters/%s", ent->d_name);
            unlink(path);
        }
    }
    closedir(d);
}

static void emit_one(const char *line) {
    char tmp[1024];
    snprintf(tmp, sizeof(tmp), "%s", line);
    char *p1 = strchr(tmp, '|');
    if (!p1) return;
    *p1 = 0;
    char *name = tmp;
    char *p2 = strchr(p1 + 1, '|');
    if (!p2) return;
    *p2 = 0;
    char *spec = p2 + 1;

    char outp[512];
    snprintf(outp, sizeof(outp), "/app/rivetbay/emitters/%s.kdec", name);
    FILE *out = fopen(outp, "w");
    if (!out) return;
    fprintf(out, "KDEC1\nNAME %s\n", name);

    char spec_copy[512];
    snprintf(spec_copy, sizeof(spec_copy), "%s", spec);
    char *save = NULL;
    for (char *tok = strtok_r(spec_copy, ",", &save); tok;
         tok = strtok_r(NULL, ",", &save)) {
        char field[64], kind[16];
        if (sscanf(tok, "%63[^:]:%15s", field, kind) == 2)
            fprintf(out, "%s %s\n", field, kind);
    }
    fclose(out);
}

void emit_all(void) {
    clear_emitters();
    char buf[65536];
    snprintf(buf, sizeof(buf), "%s", sheet_view());
    char *save = NULL;
    for (char *line = strtok_r(buf, "\n", &save); line;
         line = strtok_r(NULL, "\n", &save))
        if (*line) emit_one(line);
}
